 98→// runStatusDetailed shows the effective status plus detailed status for each settings file.
 99→func runStatusDetailed(ctx context.Context, w io.Writer, sty statusStyles, settingsPath, localSettingsPath string, projectExists, localExists bool) error {
100→	// First show the effective/merged status
101→	effectiveSettings, err := LoadEntireSettings(ctx)
102→	if err != nil {
103→		return fmt.Errorf("failed to load settings: %w", err)
104→	}
105→	fmt.Fprintln(w)
106→	fmt.Fprintln(w)
107→	fmt.Fprintln(w, formatSettingsStatusShort(ctx, effectiveSettings, sty))
108→	fmt.Fprintln(w) // blank line
109→
110→	// Show project settings if it exists
111→	if projectExists {
112→		projectSettings, err := settings.LoadFromFile(settingsPath)
113→		if err != nil {
114→			return fmt.Errorf("failed to load project settings: %w", err)
115→		}
116→		fmt.Fprintln(w, formatSettingsStatus("Project", projectSettings, sty))
117→	}
118→
119→	// Show local settings if it exists
120→	if localExists {
121→		localSettings, err := settings.LoadFromFile(localSettingsPath)
122→		if err != nil {
123→			return fmt.Errorf("failed to load local settings: %w", err)
124→		}
125→		fmt.Fprintln(w, formatSettingsStatus("Local", localSettings, sty))
126→	}
127→
128→	if effectiveSettings.Enabled {
129→		writeActiveSessions(ctx, w, sty)
130→	}
131→
132→	return nil
133→}
